// Moore FSM: all outputs determined solely by the current state and the
// inputs. There are no combinatorial next-state functions.
module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    parameter [1:0] ST_WALK_LEFT = 2'd0;
    parameter [1:0] ST_WALK_RIGHT = 2'd1;
    parameter [1:0] ST_FALL = 2'd2;
    parameter [1:0] ST_DIG_LEFT = 2'd3;
    parameter [1:0] ST_DIG_RIGHT = 2'd4;
    parameter [1:0] ST_SPLAT = 2'd5;
    reg [1:0] state, nextstate;
    reg [23:0] fall_counter;
    always @(posedge clk) begin
        if (areset) begin
            state <= ST_WALK_LEFT;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
            fall_counter <= 24'd0;
        end else begin
            state <= nextstate;
            fall_counter <= fall_counter + 24'd1;
            case (state)
                ST_WALK_LEFT: begin
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 0;
                    digging <= 0;
                    if (bump_left) nextstate = ST_WALK_RIGHT;
                    else if (ground == 0) nextstate = ST_FALL;
                    else if (dig) nextstate = ST_DIG_LEFT;
                    else nextstate = ST_WALK_LEFT;
                end
                ST_WALK_RIGHT: begin
                    walk_left <= 0;
                    walk_right <= 1;
                    aaah <= 0;
                    digging <= 0;
                    if (bump_right) nextstate = ST_WALK_LEFT;
                    else if (ground == 0) nextstate = ST_FALL;
                    else if (dig) nextstate = ST_DIG_RIGHT;
                    else nextstate = ST_WALK_RIGHT;
                end
                ST_FALL: begin
                    walk_left <= 0;
                    walk_right <= 0;
                    aaah <= 1;
                    digging <= 0;
                    if (fall_counter > 24'd20) nextstate = ST_SPLAT;
                    else if (ground) nextstate = ST_WALK_LEFT;
                    else nextstate = ST_FALL;
                end
                ST_DIG_LEFT: begin
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 0;
                    digging <= 1;
                    if (ground == 0) nextstate = ST_FALL;
                    else nextstate = ST_DIG_LEFT;
                end
                ST_DIG_RIGHT: begin
                    walk_left <= 0;
                    walk_right <= 1;
                    aaah <= 0;
                    digging <= 1;
                    if (ground == 0) nextstate = ST_FALL;
                    else nextstate = ST_DIG_RIGHT;
                end
                ST_SPLAT: begin
                    walk_left <= 0;
                    walk_right <= 0;
                    aaah <= 0;
                    digging <= 0;
                    nextstate = ST_SPLAT;
                end
                default: nextstate = ST_WALK_LEFT;
            endcase
        end
    end
endmodule

